package com.wizzadrds.theworldremembers.voice; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; class VoiceStateDeliveryTest{@Test void nervousStateChangesDelivery(){var p=new VoiceProfile("es","test",VoiceTemperament.CALM,1,1,.5f);var d=VoiceStateDelivery.from(p,VoiceState.NERVOUS);assertTrue(d.rate()>p.rate());assertTrue(d.pitch()>p.pitch());}}